const webhook = $('Webhook').first().json;
const body = webhook.body || {};
const headers = webhook.headers || {};
const etiqueta = $('Edit Fields').first().json.etiqueta;

const fbclid = body.fbclid_completo || null;
const ts = Date.now();

const record = {
  Folio:      body.folio,
  Programa:   etiqueta,
  fbp:        body.fbp || null,
  user_agent: body.user_agent || null,
  ip:         (headers['x-forwarded-for'] || '').split(',')[0].trim() || null,
  Timestamp:  ts,
};

if (fbclid) {
  record.fbclid = fbclid;
  record.fbc = 'fb.1.' + ts + '.' + fbclid;
}

return [{ json: record }];

